    ["采用位掩码如下，例：需要同时监听添加buff（1）和buff重置时间（64），可以填1+64=65\n    AddBuff = 1, -- 添加BUFF\n    RemoveBuff = 2, -- 移除BUFF\n    AddLayer = 4, -- 叠加BUFF层级\n    RemoveLayer = 8, -- 移除BUFF层级\n    AddLevel = 16, -- BUFF增加等级\n    RemoveLevel = 32, -- BUFF减少等级\n    ResetTime = 64, -- 重置时间\n    ResetMaxLayer = 128, -- 重置最大层数\n    ResetInstigatorID = 256, -- 刷新始作俑者"] = "Используется следующая битовая маска. Пример: если нужно одновременно отслеживать наложение баффа (1) и сброс времени баффа (64), укажите 1+64=65\n    AddBuff = 1, -- Наложение баффа\n    RemoveBuff = 2, -- Снятие баффа\n    AddLayer = 4, -- Накопление стаков баффа\n    RemoveLayer = 8, -- Снятие стаков баффа\n    AddLevel = 16, -- Повышение уровня баффа\n    RemoveLevel = 32, -- Понижение уровня баффа\n    ResetTime = 64, -- Сброс времени\n    ResetMaxLayer = 128, -- Сброс макс. числа стаков\n    ResetInstigatorID = 256, -- Обновление источника",
